CREATE TABLE TB_STORMAID_RESPONDER_PROFILE (
                                               RESPONDER_PROFILE_ID NUMBER(19,0) GENERATED BY DEFAULT AS IDENTITY,
                                               USER_ID NUMBER(19,0) NOT NULL,
                                               BADGE_NUMBER VARCHAR2(30 CHAR) NOT NULL,
                                               INSTITUTION_TYPE VARCHAR2(40 CHAR) NOT NULL,
                                               VERIFICATION_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
                                               AUTHORIZED_BY_USER_ID NUMBER(19,0),
                                               AUTHORIZED_AT TIMESTAMP(6),
                                               CREATED_AT TIMESTAMP(6) NOT NULL,
                                               UPDATED_AT TIMESTAMP(6) NOT NULL,
                                               CONSTRAINT PK_STORMAID_RESPONDER_PROFILE PRIMARY KEY (RESPONDER_PROFILE_ID),
                                               CONSTRAINT FK_STORMAID_RESPONDER_USER FOREIGN KEY (USER_ID) REFERENCES TB_STORMAID_USER(USER_ID),
                                               CONSTRAINT FK_STORMAID_RESPONDER_AUTH_BY FOREIGN KEY (AUTHORIZED_BY_USER_ID) REFERENCES TB_STORMAID_USER(USER_ID),
                                               CONSTRAINT UK_STORMAID_RESPONDER_USER UNIQUE (USER_ID),
                                               CONSTRAINT UK_STORMAID_RESPONDER_BADGE UNIQUE (INSTITUTION_TYPE, BADGE_NUMBER),
                                               CONSTRAINT CK_STORMAID_RESPONDER_STATUS CHECK (VERIFICATION_STATUS IN ('PENDING', 'APPROVED', 'SUSPENDED')),
                                               CONSTRAINT CK_STORMAID_RESPONDER_INSTITUTION CHECK (INSTITUTION_TYPE IN ('FIRE_DEPARTMENT', 'EMERGENCY_MEDICAL_SERVICE', 'MILITARY_POLICE', 'CIVIL_DEFENSE')),
                                               CONSTRAINT CK_STORMAID_RESPONDER_AUTHORIZED CHECK (VERIFICATION_STATUS <> 'APPROVED' OR (AUTHORIZED_AT IS NOT NULL AND AUTHORIZED_BY_USER_ID IS NOT NULL))
);